Author:     John Bieling <john@thunderbird.net>
AuthorDate: Mon Nov 11 17:01:12 2024 +0100
Commit:     John Bieling <john@thunderbird.net>
CommitDate: Mon Nov 11 17:01:12 2024 +0100

    Bug 1928826 - Re-add support to enable/disable the permission prompt for external apps, introducing mail.external_protocol_requires_permission. r=mkmelin

    Differential Revision: https://phabricator.services.mozilla.com/D227776

diff --git a/mail/app/profile/all-thunderbird.js b/mail/app/profile/all-thunderbird.js
index ccd560b761c..0467d1f9ef7 100644
--- a/mail/app/profile/all-thunderbird.js
+++ b/mail/app/profile/all-thunderbird.js
@@ -469,9 +469,6 @@ pref("security.aboutcertificate.enabled", true);
 // has on a preloaded list, it causes S/MIME failures. (Bug 1777336)
 pref("security.intermediate_preloading_healer.enabled", false);

-// Don't show a prompt for external applications.
-pref("security.external_protocol_requires_permission", false);
-
 // Prompt for the primary password prior to opening application windows,
 // to avoid the race that triggers multiple prompts (see bug 177175).
 pref("security.prompt_for_master_password_on_startup", true);
@@ -519,6 +516,10 @@ pref("spellchecker.dictionaries.download.url", "https://addons.thunderbird.net/%
 pref("alerts.totalOpenTime", 10000);
 #endif

+// Don't show a prompt for external applications (http(s):// will never prompt).
+pref("mail.external_protocol_requires_permission", false);
+
+
 // analyze urls in mail messages for scams
 pref("mail.phishing.detection.enabled", true);
 pref("mail.phishing.detection.disallow_form_actions", true);
diff --git a/mail/modules/LinkHelper.sys.mjs b/mail/modules/LinkHelper.sys.mjs
index caf09ec03c7..c6d8a05c450 100644
--- a/mail/modules/LinkHelper.sys.mjs
+++ b/mail/modules/LinkHelper.sys.mjs
@@ -11,6 +11,7 @@ import { PlacesUtils } from "resource://gre/modules/PlacesUtils.sys.mjs";
  * @param { nsIPrincipal } principal - the principal to clone and attach the
  *    permission to
  * @param {nsIURI} uri - the uri which is to be opened
+ * @param {OriginAttributesDictionary} [originAttributes]
  *
  * @returns {nsIPrincipal}
  */
@@ -40,7 +41,7 @@ export function getClonedPrincipalWithProtocolPermission(
  */
 export function getContentPrincipalWithProtocolPermission(uri) {
   const principal = Services.scriptSecurityManager.createContentPrincipal(
-    Services.io.newURI("chrome:"),
+    Services.io.newURI("chrome://messenger/content/messenger.xhtml"),
     {}
   );
   Services.perms.addFromPrincipal(
@@ -58,16 +59,12 @@ export function getContentPrincipalWithProtocolPermission(uri) {
  * @param {string|nsIURI} url - A url string or an nsIURI containing the url to
  *   open.
  * @param {object} [options]
- * @param {boolean} [options.addPermission=true] - Whether to add the permission
- *   to use the external application associated with the protocol. If permission
- *   is not added, the user will be prompted.
  * @param {boolean} [options.addToHistory=true] - Whether to add the opened url
  *   to the history.
  * @param {nsIPrincipal} [options.principal] - A triggering principal.
  */
 export function openLinkExternally(url, options) {
   const addToHistory = options?.addToHistory ?? true;
-  const addPermission = options?.permissionPrompt ?? true;

   let uri = url;
   if (!(uri instanceof Ci.nsIURI)) {
@@ -87,11 +84,15 @@ export function openLinkExternally(url, options) {
       })
       .catch(console.error);
   }
+  const isHttp = ["http", "https"].includes(uri.scheme);
+  const promptForPermission =
+    !isHttp &&
+    Services.prefs.getBoolPref("mail.external_protocol_requires_permission");

-  let principal;
-  if (addPermission) {
-    principal = options?.principal
-      ? getClonedPrincipalWithProtocolPermission(options.principal, uri)
+  let principal = options?.principal;
+  if (!promptForPermission) {
+    principal = principal
+      ? getClonedPrincipalWithProtocolPermission(principal, uri)
       : getContentPrincipalWithProtocolPermission(uri);
   }
